mapper.select:
SELECT id, ds_id, db_type, table_a, column_a, table_b, column_b, join_fields, relation_type, relation_source, knowledge_source, confidence, verified, evidence, status, version, hit_count, error_count, create_time, update_time FROM kb_relation WHERE ds_id = #{dsId} AND verified = 1 AND status = 'active'
AND relation_type = #{relationType}
AND ((table_a = #{tableA} AND table_b = #{tableB}) OR (table_a = #{tableB} AND table_b = #{tableA}))
AND (table_a = #{tableA} OR table_b = #{tableA})
AND (table_a = #{tableB} OR table_b = #{tableB})
ORDER BY confidence DESC, create_time DESC LIMIT #{topK}
